        delete_2:
          "ನಿಜವಲ್ಲದ ಆ ಕನಕ ಮೃಗವನ್ನು ಪಡೆಯುವ ಇಚ್ಛೆ ಅ ಸೀತೆಯ ಮನದಲ್ಲಿ ಬಂದದ್ದರಿಂದಲೇ ಅಲ್ಲವೇ ಆ ರಾವಣ ಆಕೆಯನ್ನು ಲಂಕೆಗೆ ಎತ್ತಿಕೊಂಡು ಹೋದದ್ದು. ಮತ್ತೆ ನಡೆದ್ದದ್ದು ರಾಮಾಯಣದ ಕಥೆ. ಇಲ್ಲಿ ಸೀತೆಯೂ ಚಪಲ ಚಿತ್ತದಿಂದ ಇಚ್ಛೆ ಪಟ್ಟಳು ಮತ್ತು ರಾವಣನೂ ಅದೇ ಚಪಲ ಚಿತ್ತದಿಂದ ಸೀತೆಯನ್ನು ಬಯಸಿದ.ಇಬ್ಬರ ಮನೋಭಾವವೂ ಒಂದೇ ಆಗಿತ್ತಲ್ಲವೆ?ಒಂದು ವಸ್ತುವಿನ ಸುಂದರತೆಯನ್ನು ನೋಡುವ ಮತ್ತು ಅದನ್ನು ಪಡೆಯಲು ಇಚ್ಛೆ ಪಡುವುದು ಸಹಜವೆ. ಆದರೆ ಅದರಿಂದ ಬರುವ ಸುಖವನ್ನೋ, ದುಃಖವನ್ನೋ, ಅನುಭವಿಸಲೇಬೇಕಲ್ಲವೇ. ಹಾಗೆಯೇ, ಸೀತೆಯೂ ಅಶೋಕವನದ ವಾಸವನ್ನು ಅನುಭವಿಸಿದಳು ಮತ್ತು ರಾವಣ ರಾಮನಿಂದ ಹತನಾದ. ಆದರೆ ಜನರು ರಾವಣನನ್ನು ದುಷ್ಟನೆಂದೂ ಜರಿಯುತ್ತಾರೆ ಮತ್ತು ಸೀತೆಯನ್ನು ಕನಿಕರಿಸುತ್ತಾರೆ.ಹೀಗೆ ಜನರು ಮಾಡುವ ವಿಶ್ಲೇಷಣೆಗೆ ವ್ಯಕ್ತಿಯ ನಿಷ್ಠೆ ಅಧಿಕವಾಗಿ ಸತ್ಯದ ಬಲವಿರುವುದಿಲ್ಲ. ಇದು ಸರ್ವೇ ಸಾಮಾನ್ಯ ನಾವು ಕಾಣುವ ಬಹುತೇಕ ವಿಷಯದಲ್ಲಿ ಸತ್ಯವಾಗಿರುತ್ತದೆ. ಜನರಿಗೆ ಒಂದು ಅಭಿಪ್ರಾಯವನ್ನು ವಹಿಸಲು ಅವರವರದೇ ಕಾರಣಗಳಿರುತ್ತದೆ. ಸತ್ಯವರಿತರೆ ಪಕ್ಷ ವಹಿಸುವ ಪ್ರಶ್ನೆ ಬರುವುದಿಲ್ಲ.",
