        kannada_explanation:
          "ಪ್ರತೀ ಶಿಶುವಿಗೂ ಒಸಡನ್ನು ಸೀಳಿಕೊಂಡು ‘ಹಲ್ಲು’ ಬರುವಾಗ ಜ್ವರ ಬರುತ್ತದೆ. ಪೂರ್ಣ ಹಲ್ಲು ಬಂದಾಗ ಆ ಜ್ವರ ಕದಿಮೆಯಾಗುತ್ತದೆ. ಹಾಗೆಯೇ ವಿಧಿ ಹೊರೆಸಿದ ನಮ್ಮ ಕರ್ಮಗಳನ್ನು ಅನುಭವಿಸಿ ಹೊರಬಂದಾಗ, ಗ್ರಹಣ ಮುಕ್ತರಾಗಿ ಅಧಿಕ ದೀಪ್ತಿಯಿಂದ ಪ್ರಜ್ವಲಿಸುವ ಸೂರ್ಯ ಚಂದ್ರರಂತೆ, ನಮ್ಮ ಉತ್ಸಾಹವೂ ಅಧಿಕವಾಗುತ್ತದೆ ಎಂದು ಉಲ್ಲೇಖಮಾಡಿದ್ದಾರೆ ಮಾನ್ಯ ಗುಂಡಪ್ಪನವರು ಈ ಮುಕ್ತಕದಲ್ಲಿ.",
        delete_2:
          "ಅನುಭವಗಳ ಒಳ ಹೊಗುವುದು, ಅನುಭವಿಸಿ ಹೊರಬರುವುದು ನಮಗೆ ವಿಧಿ ಹೊರೆಸಿದ ಹೊರೆ. ಅದನ್ನನುಭವಿಸದ ಹೊರತು ನಮಗೆ ಅನ್ಯ ದಾರಿಯಿಲ್ಲ. ಹಾಗೆ ಅನುಭವದ ಮೂಸೆಯಿಂದ ಹೊರಬಂದಾಗ ನಾವು ‘ಅನುಭವಿ’ ಗಳಾಗಿ, ಜೀವನದ ಪಾಠ ಕಲಿತು ಹೆಚ್ಚು ಬುದ್ಧಿವಂತರಾಗುತ್ತೇವೆ, ಸಾಮಾನ್ಯವಾಗಿ. ಹಾಗೆಯೇ ಆಗಬೇಕು. ಹಾಗೆ, ಅನುಭವದಿಂದ ಪಾಠ ಕಲಿತರೆ ಒಳ್ಳೆಯದು.\n\nಆದರೆ ನಮಗೆಷ್ಟು ಅನುಭವವಾದರೂ ಹಲವು ಬಾರಿ ಆ ಅನುಭವದಿಂದ ಏನನ್ನೂ ಕಲಿಯದೇ ಮತ್ತೆ ಮತ್ತೆ ಮಾಡಿದ ತಪ್ಪನ್ನೇ, ಮಾಡುತ್ತೇವೆ. ಹಾಗಾಗದೆ ಮನಸ್ಸು ಬುದ್ಧಿಗಳು, ಅನುಭವದ ಪಾಠದಿಂದ ಪಕ್ವವಾಗಿ\nನಾವು ಮತ್ತಷ್ಟು ಪ್ರಾಜ್ಞರಾಗಬೇಕು. ಎಂದು ನಾವು ಆ ಮಟ್ಟಕ್ಕೆ ತಲುಪುತ್ತೇವೋ, ಅಂದು ನಮ್ಮ ಜೀವನ ಹೆಚ್ಚು ಶಾಂತವಾಗಬಹುದು ಮತ್ತು ಆನಂದ ನಮ್ಮದಾಗಬಹುದು.",
