          "ನಮ್ಮ ಜೀವನಕೆ ದೇಹ ಮತ್ತು ಅತ್ಮಗಳೆರಡು ಅಂಗಗಳು. ಅವರೆಡೂ ಪರಸ್ಪರ ಸ್ನೇಹದಿಂದ ಇದ್ದರೆ ಒಳ್ಳೆಯದು. ಒಂದು ತನ್ನದೇ ಅವಶ್ಯಕತೆಗಳ ದಾಹದಲ್ಲಿ ಮುಳುಗಿಬಿಟ್ಟರೆ ಮತ್ತೊಂದಕ್ಕೆ ಸುಖವಿರುವುದಿಲ್ಲ. ಸಮತೋಲನವನ್ನು ಕಾಯುವು ಸಲುವಾಗಿ ಒಂದಕ್ಕೊಂದು ದ್ರೋಹಮಾಡಿಕೊಳ್ಳಬಾರದು ಎಂದು ದೇಹಾತ್ಮ ಸಂಬಂಧದ ಗಹನ ವಿಚಾರವನ್ನು ಪ್ರಸ್ತಾಪಮಾಡಿದ್ದಾರೆ ಮಾನ್ಯ ಗುಂಡಪ್ಪನವರು ಈ ಮುಕ್ತಕದಲ್ಲಿ.",
        delete_2:
          'ಆತ್ಮದ ಉದ್ದಾರಕ್ಕೆ ದೇಹವೇ ಮುಖ್ಯ ಉಪಕರಣ(ಟೂಲ್). ದೇಹವಿಲ್ಲದಿದ್ದರೆ ಆತ್ಮಕ್ಕೆ ಮುಕ್ತಿಯೇ ಇಲ್ಲ. ಆತ್ಮ ಇಂದ್ರಿಯಾತೀತವಾದದ್ದು. ಆದರೆ ದೇಹ ಇಂದ್ರಿಯ ಪ್ರೇರಿತವಾದದ್ದು. ಒಂದರ ಸೆಳೆತ ಮತ್ತೊಂದರ ಸೆಳೆತ ಬೇರೆ ಬೇರೆ ಮತ್ತು ತೀರ ವಿರುದ್ಧವಾದದ್ದು. ಆತ್ಮ ತನ್ನ ಮೂಲ ಸೇರುವ ಪ್ರಯಾಣದಲ್ಲಿ ತಾನು ಹೊತ್ತು ತಂದ ಪೂರ್ವ ಕರ್ಮಗಳನ್ನು ದೇಹದ ಮೂಲಕವೇ ನೀಗಿಕೊಳ್ಳಬೇಕು. ಆದರೆ ಪಂಚಭೂತಗಳಿಂದಾದ ದೇಹ ಇಂದ್ರಿಯ ಸುಖಗಳನ್ನೇ ಬಯಸುತ್ತಾ ಆದರಲ್ಲೇ ಮುಳುಗಿಬಿಟ್ಟರೆ ಆತ್ಮೋದ್ಧಾರದ ಮಾತು ಹಿಂದೆ ಸರಿದು ಆತ್ಮ ಸೊರಗುತ್ತದೆ. ‘ರಿಪೇರಿಯಾಗದ ಬಸ್ಸಿನಲ್ಲಿ ಕುಳಿತ ಪ್ರಯಾಣಿಕನಂತೆ.’"ರಥಂ ವಿದ್ಧಿ’ ಎಂದು ಹೇಳಿ ‘ಈ ದೇಹವನ್ನು ರಥವೆಂದು ತಿಳಿ’ ಎಂದ ಶ್ರೀ ಕೃಷ್ಣ . ರಥದಲ್ಲಿ ಕುಳಿತ ಯಜಮಾನನೇ ಆತ್ಮ. ಸಾರಥಿಯೇ ಬುದ್ಧಿ ಲಗಾಮೇ ಮನಸ್ಸು ಮತ್ತು ಓಡುವ ಕುದುರೆಗಳೇ ಅರಿಷಡ್ವರ್ಗಗಳು. ಎಲ್ಲಿಯ ತನಕ ಓಡುವ ಕುದುರೆಗಳು ಲಗಾಮಿನ ಮೂಲಕ ಸಾರಥಿಯ ಹಿಡಿತದಲ್ಲಿರುತ್ತವೆಯೋ ಅಲ್ಲಿಯ ತನಕ ಯಜಮಾನನ ಪ್ರಯಾಣ ಗಮ್ಯವನ್ನು ಸೇರುತ್ತದೆ. ಅದಲ್ಲದೆ ಸಾರಥಿಯ ಹಿಡಿತ ತಪ್ಪಿದರೆ ಎಡ್ದಾದಿಡ್ಡಿ ಪ್ರಯಾಣವಾಗಿ ಪ್ರಯಾಣಕ್ಕೆ ಹೊರಟ ಯಜಮಾನ ಸೊರಗುತ್ತಾನೆ.ಹಾಗಂದು ದೇಹಕ್ಕೆ ಪ್ರಾಮುಖ್ಯತೆ ನೀಡಬಾರದು ಎಂದಲ್ಲ, ನೀಡಬೇಕು . ಆದರೆ ಅದು ಕೇವಲ ದೇಹವನ್ನು ಸುಸ್ಥಿತಿಯಲ್ಲಿ ಇಡಲಷ್ಟೇ ಆಗಬೇಕು.ಆರೋಗ್ಯವನ್ನು ಕಾಪಾಡಿ ದೇಹ ಸುಸ್ಥಿತಿಯಲ್ಲಿದ್ದರೆ, ಮನಸ್ಸು ಬುದ್ಧಿಗಳೂ ಸಹ ಸುಸ್ಥಿತಿಯಲ್ಲಿರುತ್ತವೆ. ಇಂದ್ರಿಯಾಕರ್ಷಣೆಗಳಿಂದ ಕೂಡಿದ ಪ್ರಪಂಚದ ಸೆಳೆತಗಳಿಗೆ ಬಲಿಯಾಗದೆ, ಇರುವ ವಾಸನೆಗಳನ್ನು ದೇಹದ ಮೂಲಕವೇ ಕಳೆದುಕೊಂಡು, ಮತ್ತಷ್ಟನ್ನು ಅಂಟಿಸಿಕೊಳ್ಳದೆ ‘ರಾಕೆಟ್ ತಾನು ಹೊತ್ತ ತಂದ ಉಪಗ್ರಹವನ್ನು, ‘ತಾನು ಸುಟ್ಟು ಧರೆಗುದುರಿದರೂ’, ಆಕಾಶದಲ್ಲಿ ಅದರ ಗಮ್ಯ ಸೇರಿಸುವಂತೆ, ದೇಹ ಆತ್ಮದ ಊರ್ದ್ವಗತಿ ಪ್ರಯಾಣಕ್ಕೆ ಪೂರಕವಾಗಬೇಕೇ ಹೊರತು ತೊಡಕಾಗಬಾರದು, ಎನ್ನವುದೇ ಈ ಮುಕ್ತಕದ ಹೂರಣ.',
