        kannada_explanation:
          "ಈ ಜಗತ್ತಿನ ನಮ್ಮ ಬದುಕಿನಲ್ಲಿ, ಲೋಕದ ಆಗುಹೋಗುಗಳು ಮತ್ತು ಅವುಗಳಿಂದಾಗುವ ಪರಿಣಾಮಗಳು ನಮ್ಮ ಮನಸ್ಸಿಗೆ ಹಲವಾರು ವಿಕಾರಗಳನ್ನು ಅಂಟಿಸುತ್ತದೆ ನಮ್ಮ ಮಟ್ಟಿಗೆ ಅವು ಸತ್ಯವಲ್ಲವೇ? ಆ ಪರಿಣಾಮಗಳಿಂದಾಗುವ ಅನುಭವವೇ ನಮ್ಮ ಅರಿವಿಗೆ ಒಂದು ಮಾಪನ ಅಥವಾ ಅಳತೆ ಎಂದು ಜೀವನಾನುಭವದ ಮತ್ತು ಅದರಿಂದ ನಮ್ಮ ಮೇಲೆ ಆಗುವ ಪರಿಣಾಮದ ವಿಚಾರವನ್ನು ಮಾನ್ಯ ಗುಂಡಪ್ಪನವರು ಈ ಮುಕ್ತಕದಲ್ಲಿ ಪ್ರಸ್ತಾಪಮಾಡಿದ್ದಾರೆ.",
        delete_2:
          'ನಮ್ಮ ಅಂತರಂಗದಲ್ಲಿ ನಡೆಯುವ ವಿಚಾರ ಮತ್ತು ಅದರ ಮಂಥನಕ್ಕಿಂತ ಈ ಜಗತ್ತಿನೊಂದಿಗೆ ಮತ್ತು ಈ ಜಗತ್ತಿನ ಸಕಲ ವ್ಯಕ್ತಿ, ವಸ್ತು ಮತ್ತು ವಿಷಯದೊಂದಿಗಿನ ನಮ್ಮ ಸಂಪರ್ಕ ಮತ್ತು ಸಂಬಂಧಗಳಿಂದ ನಮ್ಮ ಮನಸ್ಸಿನ ಮೇಲಾಗುವ ಪರಿಣಾಮ ಅತ್ಯಧಿಕ. ಈ ಪರಿಣಾಮಗಳೇ ನಮ್ಮ ಒಳಗೆ ಇಳಿದು ಅನುಭವದ ಗಂಟಾಗುತ್ತದೆ. ಈ ಅನುಭವಗಳ ಸಮೂಹವೇ ನಮ್ಮ ವ್ಯಕ್ತಿತ್ವವನ್ನು ರೂಪಿಸುತ್ತದೆ.ನಮ್ಮ ಸಕಾರಾತ್ಮಕ ಗುಣಗಳಾದ, ಪ್ರೇಮ, ಕರುಣೆ, ಅನುರಾಗ, ಸಹಿಷ್ಣುತೆ ಮತ್ತು ನಕಾರಾತ್ಮಕ ಗುಣಗಳಾದ ಸಿಟ್ಟು, ಅಸಹನೆ, ಕೋಪ, ದ್ವೇಷಗಳು ಯಾವುದೂ ನಮ್ಮ ಸಂಪರ್ಕದ ವಸ್ತು, ವ್ಯಕ್ತಿ ಮತ್ತು ವಿಷಯಗಳಲ್ಲಿ ಇಲ್ಲದ್ದಿದ್ದರೂ, ಅವುಗಳಿಂದ ನಮ್ಮ ಮೇಲೆ ಪರಿಣಾಮ ಬೀರಿ ನಮಗಾಗುವ ಅನುಭವಗಳು ಸತ್ಯವಲ್ಲವೇ? ಹಾಗಾಗಿ, ನಮ್ಮ ವ್ಯಕ್ತಿತ್ವ ರೂಪಗೊಳ್ಳುವಲ್ಲಿ, ಅವುಗಳ ಪಾತ್ರವೇ ಅಧಿಕವಾಗಿರುತ್ತದೆ. ಇದನ್ನೇ ಮಾನ್ಯ ಗುಂಡಪ್ಪನವರು "ಅನುಭವವೆ ದಿಟದಳತೆ" ಎಂದಿದ್ದಾರೆ ಈ ಮುಕ್ತಕದಲ್ಲಿ.ನಾವು ಎಂದು ಆಂತರಿಕವಾಗಿ ಪಕ್ವವಾಗುತ್ತೇವೋ, ಎಂದು ನಾವು "ಕೇವಲ ಗುಣ ಗ್ರಹಣ " ಮಾಡುವ ಕ್ಷಮತೆಯನ್ನು ಬೆಳೆಸಿಕೊಳ್ಳುತ್ತೆವೋ ಅಂದು ನಮ್ಮ ವ್ಯಕ್ತಿತ್ವವೂ ಕೇವಲ ಗುಣಗಳಿಂದ ಕೂಡಿದ್ದಾಗುತ್ತದೆ. \n ಪ್ರಯತ್ನ ಪಟ್ಟರೆ ಸಾಧಿಸಬಹುದು.',
