        delete_2:
          '" ಪೂರ್ಣಮದಃ ಪೂರ್ಣಮಿದಂ ಪೂರ್ಣಾತ್ ಪೂರ್ನಾಮುದಚ್ಯತೇ ಪೂರ್ಣಸ್ಯ ಪೂರ್ಣಮಾದಾಯ ಪೂರ್ಣಮೇವಾವಶಿಷ್ಯತೆ’ ಎನ್ನುತ್ತದೆ ಈಶಾವಾಸ್ಯ ಉಪನಿಷತ್. ಅದು ಪೂರ್ಣ, ಇದು ಪೂರ್ಣ, ಪೂರ್ಣದಿಂದ ಪೂರ್ಣ ಹುಟ್ಟುತದೆ. ಪೂರ್ಣದಿಂದ ಪೂರ್ಣವನ್ನು ತೆಗೆದರೆ, ಪೂರ್ಣವೇ ಉಳಿಯುತ್ತದೆ. ಇಲ್ಲಿ ನಾವು ಪೂರ್ಣವೆನ್ನುವೆಡೆ, ಸತ್ಯವೆಂದು ಬದಲಾಯಿಸಿ ನೋಡಿದರೆ, ಒಂದು ಸಂಪೂರ್ಣ ಪರಮ ಸತ್ಯ. ಆ ಸತ್ಯದಿಂದಲೇ ಸಣ್ಣ ಸಣ್ಣ ಪೂರ್ಣ ಸತ್ಯಗಳು ಹುಟ್ಟಿವೆ ಮತ್ತು ಇವೆಲ್ಲವೂ ಇಲ್ಲವಾದಾಗ ಅಥವಾ ಒಂದಾದಾಗ ಒಂದು ಸಂಪೂರ್ಣ ಸತ್ಯವೇ ಉಳಿಯುತ್ತದೆ.ಈ ಜಗತ್ತಿನ ಎಲ್ಲವೂ ಆ ಪರಮ ಸತ್ಯದಿಂದಲೇ ಆಗಿ, ಆ ಪರಮ ಸತ್ಯದಿಂದಲೇ ಅಸ್ತಿಥ್ವದಲ್ಲಿದ್ದು ಆ ಪರಮ ಸತ್ಯದಲ್ಲೇ ಲೀನವಾಗುವ, ಆ ಪರಮಸತ್ಯದ ಪ್ರತಿರೂಪಗಳೇ ಎಂಬುವುದರಲ್ಲಿ ಸಂದೇಹವೇ ಇಲ್ಲ. ಇವುಗಳನ್ನೆಲ್ಲ ಆ ಪರಮಸತ್ಯದಿಂದ ಭಿನ್ನವಾಗಿ ನೋಡುವುದು ಪ್ರಾಕೃತ ಭಾವ. ಭಿನ್ನತೆಯನ್ನು ಕಾಣುವವರೆಗೆ ನಮಗೆ ಗುಂಡಪ್ಪನವರು ಹೇಳುವ ಆ ‘ತುಂಬುದಿಟ’ ಅರ್ಥವಾಗುವುದಿಲ್ಲ. ಸಕಲ ಜೀವರಾಶಿಗಳಲ್ಲೂ ಆ ಪರಮ ಸತ್ಯದ ಬಿಂಬವನ್ನು ಅಥವಾ ಪ್ರತಿರೂಪವನ್ನು ನೋಡುವ ಪ್ರವೃತ್ತಿಯನ್ನು ನಾವು ಬೆಳೆಸಿಕೊಂಡರೆ, ಗುಂಡಪ್ಪನವರು ಹೇಳುವ " ತುಂಬಿರುವುದೆತ್ತಲುಂ" ನ್ನು ಕಾಣಲು ನಮಗೆ ಸಾಧ್ಯವಾದರೆ ನಾವೇ ಧನ್ಯರಾಗುತ್ತೇವೆ. ನಾವೂ ಅಂತಹ ಪ್ರಯತ್ನವನ್ನು ಮಾಡೋಣವೆ?',
