        kannada_explanation:
          "ದೇಹವೆಂಬುದು ಕುದುರಯಂತೆ ಮತ್ತು ಅದನ್ನು ಸವಾರಿಮಾಡುವವನೇ ಆತ್ಮ.ತಾನು ಸವಾರಿಮಾಡುವ ವಾಹನವಾದ ದೇಹವನ್ನು ಉಪವಾಸ ಕೆಡವಿದರೆ ಪ್ರಯಾಣ ಸಾಧ್ಯವಾದೀತೆ? ಅಥವಾ ಅವರೋಹಣ ಮಾಡಿ ಪ್ರಯಾಣಮಾಡುವ ಸವಾರನಾದ ಆತ್ಮ ಎಚ್ಚರ ತಪ್ಪಿದರೆ ಪ್ರಯಾಣ ಸುಗಮವಾದೀತೇ? ಎರಡೂ ಸರಿಯಲ್ಲ. ಹಾಗಾಗಿ ಇವೆರಡಕ್ಕೂ ಸ್ನೇಹ ಇರುವುದೇ ಉಚಿತ ಎಂದು ವಿವರಿಸಿದ್ದಾರೆ ಮಾನ್ಯ ಗುಂಡಪ್ಪನವರು ಈ ಮುಕ್ತಕದಲ್ಲಿ.",
        delete_2:
          "ದೇಹಾತ್ಮ ಸಂಬಂಧವನ್ನು ಬಹಳ ಸ್ಪಷ್ಟವಾಗಿ ವಿವರಿಸುತ್ತಾ, ದೇಹವು ಸುಸ್ಥಿತಿಯಲ್ಲಿದ್ದರೆ ಆತ್ಮದ ಪ್ರಯಾಣ ಸುಗಮವಾಗುತ್ತದೆ ಎಂದಿದ್ದಾರೆ ಮಾನ್ಯ ಗುಂಡಪ್ಪನವರು. ಕೃಶವಾದ, ಅನಾರೋಗ್ಯದಿಂದ ನರಳುವ ದೇಹದಲ್ಲಿ ಆತ್ಮ ಚಿಂತನೆ ಬರುವುದಕ್ಕೆ ಸಾಧ್ಯವೇ ಇಲ್ಲ. ಅಂತಹ ದೇಹವನ್ನು ಹೊತ್ತ ಆತ್ಮ ಸೊರಗುತ್ತದೆ. ಏಕೆಂದರೆ ಮನಸ್ಸು ಬುದ್ಧಿಗಳು ಸದಾಕಾಲ ರೋಗಿಷ್ಠ, ನರಳುವ ಮತ್ತು ನೋವನ್ನು ಅನುಭವಿಸುವ ದೇಹದ ಚಿಂತೆಯಲ್ಲಿಯೇ ಮಗ್ನವಾಗಿರುವಾಗ, ಆತ್ಮ ಚಿಂತನೆ ಮತ್ತು ಪರಮಾತ್ಮ ಚಿಂತನೆಗೆ ಎಡೆಯೆಲ್ಲಿ? ಹಾಗಾಗಿ ಸದೃಢ, ಆರೋಗ್ಯವಂತ ದೇಹವಿದ್ದರೆ ತನ್ನ ಮೂಲ ಸೇರುವ, ಆತ್ಮದ ಪ್ರಯಾಣ ಸುಗಮವಾದೀತು.‘ರೋಹಿ ಜಾಗ್ರತೆದಪ್ಪೆ’ ಎಂದಿದ್ದಾರೆ ಮಾನ್ಯ ಗುಂಡಪ್ಪನವರು. ಅರ್ಥಾತ್, ಮನಸ್ಸು ಬುದ್ಧಿ ದೇಹಗಳ ಸಹಕಾರ ಮತ್ತು ಸಹವಾಸದಿಂದ ಪ್ರಯಾಣ ಮುಂದುವರೆಸುವ ಆತ್ಮವೂ ಸಹ ಎಚ್ಚರದಿಂದಿದ್ದು,ಅವುಗಳು ಸನ್ಮಾರ್ಗದಲ್ಲಿದ್ದು, ಕೇವಲ ‘ಗುಣ ಗ್ರಹಣ’ವನ್ನು ಮಾಡುತ್ತಾ ಇವೆಯೇ ಎಂದು ಎಚ್ಚರಿದಿಂದಿದ್ದು ತನ್ನ ಪ್ರಯಾಣದ ಮಾರ್ಗ ಸುಗಮವಾಗಿಸಿಕೊಳ್ಳಬೇಕು.ಹಾಗಾದರೆ ಆರೋಗ್ಯವಂತರಾದವರೆಲ್ಲರೂ ಆಧ್ಯಾತ್ಮಿಕವಾಗಿ ಮುನ್ನಡೆಯುತ್ತಾರೆಂದು ಅರ್ಥವಲ್ಲ. ಆರೋಗ್ಯವಂತ ದೇಹ ಕೇವಲ ‘ಒಂದು ಉಪಕರಣ’. ಅದಕ್ಕೆ ಪೂರಕವಾಗಿ ಸದಾಚಾರ, ಸದ್ವಿಚಾರ, ಸತ್ಸಂಗ, ಮತ್ತು ಸತ್ ಪ್ರಯತ್ನಗಳೂ ಸಹ ಈ ಪ್ರಯಾಣಕ್ಕೆ ಪೂರಕವಾಗಿರುತ್ತವೆ. ಆದರೆ ಇವೆಲ್ಲವೂ ಸಾಧ್ಯವಾಗುವುದು ದೇಹ ಸ್ಥಿರವಾಗಿದ್ದರೆ ಮಾತ್ರ. ಹಾಗಾಗಿ ದೇಹವನ್ನು ಆರೋಗ್ಯವಾಗಿಟ್ಟುಕೊಂಡು, ಮೇಲೆ ಹೇಳಿದ ಮಿಕ್ಕೆಲ್ಲದರ ಸಹಾಯದಿಂದ ನಮ್ಮಆಧ್ಯಾತ್ಮಿಕ ಪ್ರಯಾಣ ಸಾಗಿಸಿದರೆ ಅದು ಸುಗಮವಾಗುತ್ತದೆ. ಅಂತಹ ಪ್ರಯತ್ನವನ್ನು ನಾವೆಲ್ಲಾ ಮಾಡಬೇಕು ಎನ್ನುವುದೇ ಈ ಮುಕ್ತಕದ ಆಶಯ.",
