        delete_2:
          'ಎಲ್ಲಿಂದಲೋ ಬಂದು ಈ ದೇಹವನ್ನು ಹೊಕ್ಕು ಈ ದೇಹವನ್ನು ತನ್ನ ಪ್ರಯಾಣಕ್ಕಾಗಿ ಒಂದು ವಾಹನದಂತೆ ಉಪಯೋಗಿಸುವ ಆತ್ಮಕ್ಕೆ ಈ ದೇಹವು ಬಹಳ ಮುಖ್ಯ ಮತ್ತು ತಾಯ ಗರ್ಭದಲ್ಲಿ ರೂಪುಗೊಂಡ ಆ ದೇಹಕ್ಕೆ ಈ ಜಗತ್ತಿನ ದರ್ಶನ ಕೇವಲ ಆತ್ಮದಿಂದ ಅಥವಾ ಚೇತನದಿಂದಲೇ ಸಾಧ್ಯ.ಈ ಜಗತ್ತಿನಾಟ ನಡೆಯುವುದು ದೇಹ ಮತ್ತು ಆತ್ಮದ ಪರಸ್ಪರ ಪೂರಕವಾದ ಅಸ್ತಿತ್ವದಿಂದ. ಹಾಗಾಗಿ ನಮ್ಮ ಬದುಕಿನಲ್ಲಿ ಇವೆರಡಕ್ಕೂ ಸಮಾನವಾದ ಮಹತ್ವವನ್ನು ನೀಡಬೇಕು.ನಮ್ಮ ಈ ಜಗತ್ತಿನ ಬದುಕಿನಲ್ಲಿ ಹಿಂದೆಯೂ ಇದ್ದು ತಾಯಗರ್ಭದಲ್ಲಿಯ ದೇಹವನ್ನು ಧರಿಸುವ ಆತ್ಮವನ್ನು ತಾಯಂತೆಯೂ ಮತ್ತು ಆ ತಾಯ ಗರ್ಭದಿಂದ ನಂತರ ಹೊರಬಂದ ಈ ದೇಹವನ್ನು, ನಮ್ಮ ಬದುಕಿನಲ್ಲಿ ನಂತರ ಬರುವ ಮಡದಿಯಂತೆಯೂ ನೋಡಬೇಕು ಎಂದಿದ್ದಾರೆ ಮಾನ್ಯ ಗುಂಡಪ್ಪನವರು.ಹೇಗೆ ಸಂಸಾರದಲ್ಲಿ ಸಮನ್ವಯತೆಯನ್ನು ಕಾಪಾಡಲು ಹೆತ್ತ ತಾಯಿ ಮತ್ತು ಕಟ್ಟಿಕೊಂಡ ಹೆಂಡತಿಯನ್ನು ಸಮನಾಗಿ ನೋಡಬೇಕಾಗುತ್ತದೋ ಹಾಗೆಯೇ ದೇಹ ಮತ್ತು ಆತ್ಮಗಳೊಂದಿಗೆ ‘ಅವರಾಯವನು ಸರಿನೋಡು" ಎಂದು ಡಿ.ವಿ.ಜಿ ಯವರು ಹೇಳುವಂತೆ ಆಯವರಿತು \n ನಡೆದುಕೊಳ್ಳಬೇಕು ಎಂಬುದೇ ಈ ಮುಕ್ತಕದ ಹೂರಣ.',
