          "ಈ ಜಗತ್ತು ಜಡ ಮತ್ತು ಚೇತನದಿಂದ ಆಗಿದೆ. ಜಡಕ್ಕೆ ರೂಪವುಂಟು. ಚೇತನಕ್ಕೆ ರೂಪವಿಲ್ಲ. ಆದರೆ ಆ ಜಡದ ರೂಪ ಬದಲಾಗುತ್ತಾ ಇರುತ್ತದೆ. ಯಾವ ರೂಪವೂ ಶಾಶ್ವತವಾಗಿರುವುದಿಲ್ಲ. ಚೇತನಕ್ಕೆ ಮಾತ್ರ ನಾಶವಿಲ್ಲ. ಅದು ಅನಶ್ಯ. ಜಡದ ಈಗಿನ ರೂಪ ನಾಶವಾಗಿ ಮತ್ತೊಂದು ರೂಪವನ್ನು ಪಡೆದುಕೊಂಡರೂ ನಾವು ನೋಡುವಾಗಿನ ರೂಪ ನಮಗೆ ಸತ್ಯವಲ್ಲವೆ. ಅದನ್ನು ನೋಡುವುದಷ್ಟೇ ನಮ್ಮ ಕರ್ತವ್ಯ.ಉದಾಹರಣೆಗೆ, ಒಂದು ಪುಟ್ಟ ಮಗು, ಮಗುವಾಗೇ ಇರದೆ, ಬಾಲಕ(ಕಿ)ನಾಗಿ ಯುವಕ(ತಿ)ನಾಗಿ, ವಯಸ್ಕನಾಗಿ, ಮುದುಕ(ಕಿ)ನಾಗಿ, ಒಂದು ದಿನ ಆ ರೂಪವೂ ಇಲ್ಲದೆ ಮಣ್ಣಲ್ಲಿ ಮಣ್ಣಾಗಿ ಹೋಗುತ್ತಾನೆ. ಹೀಗೆ ಬದಲಾಗುತ್ತಾ ಹೋಗುವ ರೂಪವು ಶಾಶ್ವತವಲ್ಲದಿದ್ದರೂ ಆಯಾಯಾ ಅವಸ್ಥೆಗಳಲ್ಲಿ ನಾವು ನೋಡುವುದು ದೃಶ್ಯ (ಕಾಣಬಹುದಾದದ್ದು), ಸತ್ಯವಲ್ಲವೇ?ಇನ್ನು ಚೇತನಕ್ಕೆ ರೂಪವಿಲ್ಲ.ಅದನ್ನು ರೂಪಗಳ ಮೂಲಕ, ಕೇವಲ ಅನುಭವದಿಂದ ಅರಿಯಬಹುದು. ಆದರೆ ಅದು ಶಾಶ್ವತ ಮತ್ತು ನಿರಂತರ. ನಾವು ಕಾಣುವಂತಾ ಮತ್ತು ಬದಲಾಗುತ್ತಾ ಹೋಗುವ ರೂಪ ಮತ್ತು ಕಾಣಲಾಗದ ಚೇತನಗಳ ಸಮ್ಮಿಲನವೇ ಈ ಜಗತ್ತು. ಕಾಣುವಂತಾ ರೂಪ, ಎಂದರೆ ಈ ದೇಹ. ಈ ಜಗತ್ತಿನ ಅನುಭವ ಪಡೆಯುವುದೇ ಆ ಕಾಣಲಾಗದ ಚೇತನದ ಮೂಲಕ ಮತ್ತು ಈ ಕಾಣಲಾಗದ ಚೇತನ ತನ್ನ ಜಗತ್ತಿನ ಪಯಣವನ್ನು ನಡೆಸುವುದೇ ಬದಲಾಗುತ್ತಾ ಹೋಗುವ ರೂಪ ಹೊಂದಿದ ಈ ದೇಹದ ಮೂಲಕ. ಮಾನ್ಯ ಗುಂಡಪ್ಪನವರು ‘ವಿಶ್ವಾನುಭವವೆ ವಿಶ್ವಾತ್ಮಾನುಭವಕೆ ಪಥ’ ಎಂದರು.ಪರಮ ಚೇತನವನ್ನು ಅರಿಯುವುದೇ ಆಧ್ಯಾತ್ಮದ ಗುರಿ. ಆದರೆ ‘ಅವಿನಾಶಿ’ಯಾದ ಆ ಪರಮ ಚೇತನವನ್ನು ಅರಿಯಲು ‘ನಾಶಿ’ಯಾದ ಈ ದೇಹದ ಅಥವಾ ರೂಪದ ಮೂಲಕವೇ ಸಾಧ್ಯ ಎಂದು ‘ಜಡ ಮತ್ತು ಜೀವ’ಗಳ ಒಂದು ಅವಿನಾಭಾವ ಸಂಬಂಧವೇ ಈ ಮುಕ್ತಕದ ಹೂರಣ.",
