        delete_2:
          '‘ಬಡಿತವಿರವನಕ ಬಡಿವಾರವಿರಬೇಕು’ ಎಂದು ಹೇಳಿದ ಸ್ನೇಹಿತರ ಮಾತು ಜ್ಞಾಪಕಕ್ಕೆ ಬರುತ್ತದೆ.ಈ ಜಗತ್ತಿನಲ್ಲಿ ಇದ್ದಮೇಲೆ, ಬದುಕಬೇಕು. ಇಲ್ಲಿನ ಕಷ್ಟಗಳ ಸರಮಾಲೆಯನ್ನು ಹೊತ್ತು, ‘ಈ ಜೀವನ ಎಂದಾದರೂ ಒಂದು ದಿನ ಕೊನೆಯಾಗುತ್ತದೆ ಅಥವಾ ನಶ್ವರವಾದ ಈ ಬದುಕಿನಿಂದ ಏನಾಗಬೇಕು’ ಎಂದು ಹೇಳುವವರಿಗೇನೂ ಕಡಿಮೆ ಇಲ್ಲ. ಅದು ಒಣ ವೇದಾಂತ. ರೋಗಿ ಸಾಯುವತನಕ ವೈದ್ಯರು ಶುಶ್ರೂಷೆ ಮಾಡುವುದಿಲ್ಲವೇ? ಹಾಗೆ, ಈ ಜೀವ ಮತ್ತು ದೇಹದ ಸಂಬಂಧವಿರುವ ತನಕ, ಬದುಕಲೇ ಬೇಕು. ಅನಾಸಕ್ತಿಯಿಂದ ಬದುಕುವುದಕ್ಕಿಂತ ಸಾಯುವುದೇ ಲೇಸು.ತನ್ನ ಕರ್ಮಶೇಷವನ್ನು ಕಳೆಯಲು ಜೀವ ದೇಹಧಾರಣೆ ಮಾಡುತ್ತದೆ. ಕಷ್ಟ ಅಥವಾ ಸುಖಗಳನ್ನು ಅನುಭವಿಸುವ ಮೂಲಕವೇ ಕರ್ಮ ಶೇಷವನ್ನು ಕಳೆಯಲು ಸಾಧ್ಯ. ಅಸಹನೀಯ ಕಷ್ಟಗಳನ್ನು ಅನುಭವಿಸುವಾಗ" ಅಯ್ಯೋ ಈ ಜೀವನ ಸಾಕು ಸಾಕಾಗಿದೆ" ಎಂದು ಬದುಕುವುದನ್ನು ಮತ್ತು ಬದುಕಿನ ಜಂಜಾಟವನ್ನು ಅನುಭವಿಸುವುದನ್ನು ಬಿಟ್ಟರೆ ಕರ್ಮ ಕಳೆಯುವುದೆಂತು? ಹಾಗಾಗಿ ಬದುಕಲೇ ಬೇಕು. ಪ್ರಾಣವಿರುವ ತನಕ ಬದುಕಲೇಬೇಕು. ಈ ದೇಹಕ್ಕೆ ಅವಶ್ಯಕ ಉಪಚಾರವನ್ನು ಮಾಡುತ್ತಾ, ಅದನ್ನು ಸುಸ್ಥಿತಿಯಲ್ಲಿ ಇಟ್ಟುಕೊಂಡು, ಜೀವನ ಪ್ರಯಾಣವನ್ನು ಸುಗಮವಾಗಿಸಬೇಕು.ಆದರೆ ಹಾಗೆ ಬದುಕುವಾಗ, ಮಾನ್ಯ ಗುಂಡಪ್ಪನವರು" ಚರಿಸು ನೀನಾಳಾಗಿ" ಎಂದು ಹೇಳುವಂತೆ, ಒಬ್ಬ ಆಳು ಅಥವಾ ಸೇವಕ ತನ್ನ ಯಜಮಾನ ನಿಗದಿಸಿದ ಕೆಲಸವನ್ನು ಆಸಕ್ತಿಯಿಂದ ಮಾಡಿದರೂ ಅದರ ಫಲಾಫಲಗಳನ್ನು ಆ ಯಜಮಾನನಿಗೇ ಸಮರ್ಪಿಸುವಹಾಗೆ, ಒಂದು ನಿರ್ಲಿಪ್ತ ಭಾವದಿಂದ, ಅಂಟೀ ಅಂಟದ ಹಾಗೆ ಬದುಕಿದರೆ ಬದುಕಿನಲ್ಲಿ ನಿಜವಾದ ಆನಂದವನ್ನು ಪಡೆಯಬಹುದು.',
