        kannada_explanation:
          "ಹೇಗೆ ರತ್ನಹಾರದಲ್ಲಿ ಒಂದು ರತ್ನಕ್ಕೂ ಮತ್ತೊಂದಕ್ಕೂ ಮಧ್ಯೆ ಚಿನ್ನದ ಗೆರೆಯಿರಿಸಿ ರತ್ನದ ಹೊಳಪನ್ನು ಅಧಿಕವಾಗಿಸುತ್ತಾರೋ, ಹೇಗೆ ನೆರಳು ತಾನಿದ್ದು ಬೆಳಕಿಗೆ ಪ್ರಾಮುಖ್ಯತೆ ನೀಡುತ್ತದೋ, ಹೇಗೆ ಹೊಲ ಗದ್ದೆಗಳಲ್ಲಿ ಪೈರ ಸಾಲ ನಡುವಿನ ಬದಿ ತನ್ನ ಚೌಕಟ್ಟಿನಲ್ಲಿರುವ ಬೆಳೆಯನ್ನು ಕಾಯುತ್ತದೋ, ಹಾಗೆಯೇ ಉಳಿವಿಗೆ ಅಳಿವು ಪೂರಕವಾಗಿರುತ್ತದೆ ಎಂದು ಪ್ರಸ್ತಾಪಿಸಿದ್ದಾರೆ ಮಾನ್ಯ ಗುಂಡಪ್ಪನವರು ಈ ಮುಕ್ತಕದಲ್ಲಿ.",
        delete_2:
          'ಬದುಕೇ ಹಾಗೆ. ಪರಸ್ಪರ ವಿರೋಧವಾದರೂ ಒಂದರ ಪಕ್ಕದಲ್ಲಿ ಒಂದು ಇದ್ದೇ ಇರುತ್ತದೆ. " ರಾಮನಿರ್ದಂದು ರಾವಣನೊಬ್ಬನಿರ್ದನಲ"(ಮುಕ್ತಕ ೨೮೮) ಮತ್ತು ದರಿಯಿರದೆ ಗಿರಿಯಿಲ್ಲ, ನೆರಳಿರದೆ ಬೆಳಕಿಲ್ಲ( ಮುಕ್ತಕ ೨೯೩) " ಎಂದು ಗುಂಡಪ್ಪನವರೇ ಹೇಳುವಂತೆ, ಜಗತ್ತಿನಲ್ಲಿ ಗುಣವಿರೋಧವಿರುವ ಹಲವಾರು ಒಂದಕ್ಕೊಂದು ಪೂರಕವಾಗಿ ಇರುತ್ತವೆ. ರಾವಣನೊಬ್ಬ ಇದ್ದದ್ದರಿಂದ ‘ ರಾಮ’ ನಿಗೆ ಪ್ರಾಮುಖ್ಯತೆ.ಹಾಗೆಯೇ ಕಹಿ ಇದ್ದರೆ ಸಿಹಿಗೆ ಬೆಲೆ, ದುಷ್ಟತನವಿದ್ದರೆ ಸಜ್ಜನಿಕೆಗೆ ಬೆಲೆ. ಕಷ್ಟವಿದ್ದರೆ ಸುಖಕ್ಕೆ ಬೆಲೆ. ವಾತಾವರಣದಲ್ಲಿ ತಾಪಮಾನ ಹೆಚ್ಚಾದಾಗ ಅಧಿಕ ಮಳೆ ಬರುತ್ತದೆ. ಮಳೆಗೆ ತಾಪ ಕಾರಣವಾದರೂ ತಾಪದ ಅಂತ್ಯಕ್ಕೆ ಮಳೆ ಕಾರಣವಾಗುತ್ತದೆ.ಒಂದು ಬೀಜ ತಾನಿಲ್ಲವಾದಾಗ ಮಾತ್ರ ಹಲವಾರು ಬೀಜಗಳ ಹುಟ್ಟಿಗೆ ಕಾರಣವಾಗುತ್ತದೆ. ಹೀಗೆ ಒಂದರ ಅಳಿವು ಮತ್ತೊಂದರ ಉಳಿವಿಗೆ ಪೂರಕವಾಗಿರುತ್ತದೆ.ಆ ಪರಮಾತ್ಮನ ಸೃಷ್ಟಿಯಲ್ಲಿರುವ ಅಸಮತೆಯೇ ಈ ಜಗತ್ತು ಇಷ್ಟೊಂದು ಸುಂದರವಾಗಿರುವುದಕ್ಕೆ ಕಾರಣ.ಈ ಮುಕ್ತಕದಲ್ಲಿ ಗುಂಡಪ್ಪನವರು "ಉಳಿವಿಗಳಿವಿನ ನೆರೆಯೊ" ಎಂದು ಹೇಳುವಂತೆ ಸೃಷ್ಟಿಯಲ್ಲಿ ಒಂದರ ಅಳಿವಿನಿಂದಲೇ ಮತ್ತೊಂದರ ಉಳಿವು ಸಾಧ್ಯವಾಗುತ್ತದೆ, ಎಂಬುದೇ ಈ ಮುಕ್ತಕದ ಹೂರಣ.',
