        kannada_explanation:
          "ಹಿಂದಿನ ಮುಕ್ತಕದಲ್ಲಿ ಉಲ್ಲೇಖಗೊಂಡಿರುವ ನರ ನಾರಿಯರ ಪರಸ್ಪರ ಆಕರ್ಷಣೆ ಮತ್ತು ವ್ಯಾಮೋಹದಿಂದ ಮೊದಲಾಗಿ ಅತಿ ಒರಟನಾಗಿದ್ದ ಮನುಷ್ಯ, ಕಾಲಾನುಕಾಲಕ್ಕೆ ‘ನಯವನ್ನು’ ತನ್ನ ನಡವಳಿಕೆಯಲ್ಲಿ ತಂದುಕೊಂಡ, ತನ್ನದೇ ಬಾಳಿಗೆ ಒಂದು ನಿಯಮವನ್ನು ಸೃಷ್ಟಿಸಿಕೊಂಡು ಪಾಲಿಸತೊಡಗಿದ. ಅವನ ಕುಲಗಳು ಬೆಳೆದವು, ಗೋತ್ರಗಳು, ಹುಟ್ಟಿಕೊಂಡವು. ತತ್ಕಾರಣವಾಗಿ ರಾಜ್ಯ,ಮಠ,ಧರ್ಮ ಸಂಸ್ಥೆಗಳು ಹುಟ್ಟಿಕೊಂಡವು. ಇವನ ಅನುಭವ ಹೆಚ್ಚಾಗಿ, ಜ್ಞಾನ ಮೂಡಿ, ಬದುಕಿನ ನಶ್ವರತೆಯನ್ನು ಮನಗಂಡು, ಜಗತ್ತಿನ ಮೇಲಿನ ಮಮತೆಯನ್ನು ಕಡಿಮೆ ಮಾಡಿಕೊಳ್ಳುತ್ತಾ, ಅದರಿಂದ ಆತ್ಮ ವಿಕಾಸದತ್ತ ತನ್ನ ಗಮನ ಹರಿಸ ತೊಡಗಿದ, ಎನ್ನುವುದೇ, ಮಾನ್ಯ ಗುಂಡಪ್ಪನವರ ಈ ಮುಕ್ತಕದ ಹೂರಣ.",
        delete_2:
          "ಮನುಷ್ಯ ಕಾಡಿನಲ್ಲಿ ವಾಸಿಸುತ್ತಿದ್ದಾಗ, ಅನ್ಯ ಪ್ರಾಣಿಗಳಂತೆ ಅವನ ಅವಶ್ಯಕತೆಗಳು, ಕೇವಲ, ಆಹಾರ, ಸ್ವಸಂರಕ್ಷಣೆ ಮತ್ತು ಸಂತಾನೋತ್ಪತ್ತಿಗೆ ಸೀಮಿತವಾಗಿತ್ತು. ಆದರೆ ನಾಗರೀಕತೆ ಬೆಳೆಯುತ್ತಾ ಹೋದಂತೆ, ಇವನ ಗುಂಪುಗಳೇ, ಕುಲಗಳಾದವು. ಆಯಾಯಾ ಕುಲಕ್ಕೆ ಅದರದ್ದೇ ಹೆಸರು ನಿಯಮ, ನೀತಿ, ಧರ್ಮ, ಒಬ್ಬ ಧರ್ಮಗುರು, ಎಲ್ಲಾ ಹುಟ್ಟಿಕೊಂಡವು. ತಾನು ಕಟ್ಟಿಕೊಂಡ ಇವುಗಳನ್ನು ಕಾಯಲು, ಮನುಷ್ಯ ಸ್ವಾರ್ಥನಾಗುತ್ತಾ ಹೋದ. ಕುಲ ಕುಲಗಳ ನಡುವೆ ದ್ವೇಷ ಮತ್ತು ಕಲಹಗಳು,ಅಲ್ಲಿಂದಲೇ ಮೊದಲಾಯಿತು.ವಿಕಸಿತ ಸ್ಥರದಲ್ಲಿ ಮನುಷ್ಯನ ಜ್ಞಾನಾರ್ಜನೆಯ ಕೆಲಸವೂ ಮುಂದುವರೆದು, ಹಲವರಲ್ಲಿ ಸಜ್ಜನಿಕೆ, ಸದ್ಭಾವನೆ ಮೂಡಿ, ಸತ್ಯದ ಮತ್ತು ಸತ್ವದ ಅರಿವಾಗಿ, ತಾನು ಅನುಭವಿಸುತ್ತಿರುವ ಜಗತ್ತಿನ, ನಶ್ವರತೆಯನ್ನು ಮನಗಂಡು, ಆತ್ಮ ವಿಕಾಸಕ್ಕೆ ಬೇಕಾದ ಸಂಸ್ಕಾರಗಳು, ವಿದ್ಯೆ, ನಾಗರೀಕತೆ, ಆಚಾರ ವಿಚಾರಗಳನ್ನು ಮನುಷ್ಯ ರೂಢಿಸಿಕೊಳ್ಳುತ್ತಾ ಹೋದಾಗ ಆತ್ಮ ವಿಕಾಸಕ್ಕೆ ದಾರಿಯಾಯಿತು. ಆದರೆ ಜಗತ್ತಿಗೆ ಕಾರಣವಾದ ಪರಮ ಚೇತನ ಒಂದೇ ಆದರೂ ಅದನ್ನರಿಯುವ ದಾರಿಗಳು ಬೇರೆ ಬೇರೆಯಾದವು. ಹಾಗಾಗಿಯೇ ಇಂದು ಈ ಜಗತ್ತಿನಲ್ಲಿ ಇಷ್ಟೊಂದು ವಿಚಾರ ಬೇಧಗಳು,ಮತಗಳು. ಎಲ್ಲರ ಗಮ್ಯವೂ ಒಂದೇ ಆದರೂ, ಅದನ್ನು ಸೇರಲು ಹತ್ತು ಹಲವಾರು ಕವಲು ದಾರಿಗಳು.ಎಂದು ಎಲ್ಲ ದಾರಿಗಳೂ ಒಂದಾಗಿ ಸೇರಿ ಎಲ್ಲರೂ ಒಂದಾಗಿ ಬದುಕಿ, ಬಾಳಿ, ಒಂದೇ ಮಾರ್ಗದಲ್ಲಿ ಆತ್ಮೋದ್ಧಾರಕ್ಕೆ ಪ್ರಯತ್ನನಡೆಯುತ್ತದೆಯೋ, ಅಂದು ಇಹದಲ್ಲೂ ಸುಖ ಮತ್ತು ಪರದಲ್ಲೂ ಸುಖ.",
